        ScoreRow: {
            complex_id: number;
            name: string;
            living_area?: string | null;
            living_area_name?: string | null;
            score_run_id?: number | null;
            total: components["schemas"]["Fact"];
            rank: number | null;
            tie_group: number | null;
            unstable: boolean;
            p10: components["schemas"]["Fact"];
            components: components["schemas"]["Components"];
            delta_rerank?: components["schemas"]["Fact"] | null;
            intake: components["schemas"]["Intake"] | null;
            decision?: components["schemas"]["DecisionBadge"] | null;
            judge_scope: components["schemas"]["JudgeScope"];
            /** @description 계약 2026-10-09.20(D28-5 Q7): 현재 구매가 아래(§6-1) — 같은 리비전 목록 행 ComplexRow.price_low 와 같은 Fact(같은 함수·같은 출처). 발행 리비전은 발행 때 값(저장본, D10-1·D13-1). .20 이전 발행 리비전 저장본에는 키가 없다(= null) */
            price_low?: components["schemas"]["Fact"] | null;
            /** @description 현재 구매가 위 — ComplexRow.price_high 와 같은 Fact(price_low 와 같은 규칙) */
            price_high?: components["schemas"]["Fact"] | null;
            /** @description 전매 종료일 — ComplexRow.resale_end 와 같은 Fact(price_low 와 같은 규칙) */
            resale_end?: components["schemas"]["Fact"] | null;
            /** @description 입주 예정 연월 — ComplexRow.move_in_ym 과 같은 Fact(price_low 와 같은 규칙) */
            move_in_ym?: components["schemas"]["Fact"] | null;
            /** @description 가격 갭 퍼센트 — ComplexRow.gap_pct 와 같은 Fact(성분 원값, prov 'sc_<실행>_<단지>_gap.raw'). 성분 점수 s_gap 은 components.gap.score */
            gap_pct?: components["schemas"]["Fact"] | null;
            /** @description 계약 2026-10-09.20(D28-5 Q4): 경쟁률 요약 — ComplexRow.competition_summary 와 같은 값 */
            competition_summary?: components["schemas"]["CompetitionSummary"] | null;
            /**
             * @description D10-1(계약 2026-10-09.6): 이 행의 범위·순위·총점·성분은 그 스냅샷 score_run 의 **저장값**이다. 현재 사실로 계산한 판정 범위(analysis/scope.py)가 저장된 범위와 다르면 true — 화면은 '재판정 필요' 배지 + rejudge 잡 제안만 하고 저장값과 현재값을 한 행에 섞지 않는다. 없으면 false.
             * @default false
             */
            rejudge_needed?: boolean;
        };
        /**
         * ScoreRunResult
         * @description ScoreEngine.run(snapshot, scenario, inputs)의 결과 = score_run 1행 + score_component·score_total 행들 (RA §3, §4-3, §6). 순수 함수 결과라 같은 inputs면 같은 값이다.
         *     종합 S = Σ w_i s_i — 10진 연산(Decimal)으로 계산해 원값을 total에 저장한다(부동소수 합을 쓰면 5.325가 5.3249…가 되어 반올림이 바뀐다). 성분 중 하나라도 score_0_10=null이면 total=null(미계산), rank=null.
         *     동점(§6-4): 정렬은 total 내림차순(동률이면 complex_id 오름차순). 그룹의 첫 단지(리더)와 |ΔS| < 0.05 인 뒤따르는 단지는 같은 tie_group·같은 rank(공동 순위). rank는 경쟁 순위(1,2,2,4): 그룹 rank = 1 + 그룹 앞 단지 수. 비교는 반올림 전 원값으로 한다. tie_group은 1부터 매기고 단독 단지는 null.
         *     unstable: 민감도 12변형 중 하나라도 TOP 5 집합(rank ≤ 5인 단지 전부 — 공동 5위 포함)이 바뀌면 그 집합에 들어오거나 나간 단지 true.
         * @example {
         *       "score_run_id": 88,
         *       "snapshot_id": 12,
         *       "scenario_id": 1,
         *       "weights": {
         *         "p10": 0.35,
         *         "rerank": 0.2,
         *         "gap": 0.15,
         *         "benchmark": 0.1,
         *         "supply": 0.1,
         *         "liquidity": 0.1
         *       },
         *       "rerank_judgment_seq": 124,
         *       "prev_score_run_id": 71,
         *       "created_at": "2026-10-08T07:30:00+09:00",
         *       "components": [
         *         {
         *           "complex_id": 5,
         *           "component": "p10",
         *           "raw_value": 0.26,
         *           "score_0_10": 2.6,
         *           "formula_text": "10 × 0.26 = 2.6 (jl_70)",
         *           "label": "추정",
         *           "reason": null,
         *           "delta": null,
         *           "flags": []
         *         }
         *       ],
         *       "totals": [
         *         {
         *           "complex_id": 1,
         *           "total": 5.87,
         *           "rank": 1,
         *           "tie_group": null,
         *           "unstable": false
         *         },
         *         {
         *           "complex_id": 5,
         *           "total": 4.61,
         *           "rank": 5,
         *           "tie_group": 1,
         *           "unstable": true
         *         },
         *         {
         *           "complex_id": 6,
         *           "total": 4.605,
         *           "rank": 5,
         *           "tie_group": 1,
         *           "unstable": true
         *         }
         *       ]
         *     }
         */
        ScoreRunResult: {
            score_run_id?: number | null;
            snapshot_id: number;
            scenario_id: number;
            weights: components["schemas"]["Weights"];
            /** @description 이 run의 rerank 값이 나온 단 하나의 호출(§6-5) */
            rerank_judgment_seq: number | null;
            /** @description delta_rerank 비교 대상 run */
            prev_score_run_id?: number | null;
            /** Format: date-time */
            created_at?: string | null;
            components: components["schemas"]["ScoreComponent"][];
            totals: components["schemas"]["ScoreTotal"][];
        };
        /**
         * ScoreTotal
         * @description score_total 1행. (score_run_id, complex_id) 유일.
         */
        ScoreTotal: {
            complex_id: number;
            total: number | null;
            rank: number | null;
            tie_group: number | null;
            unstable: boolean;
        };
        /**
         * ScreenResult
         * @description P1 입력 검사. verdict=block이면 그 입력은 사용 금지, skip이면 purpose를 바꿔 다른 입력으로 재스크린.
         */
        ScreenResult: {
            /** @enum {string} */
            verdict: "pass" | "skip" | "block";
            injection?: number | null;
            substance?: number | null;
            relevance?: number | null;
        };
